"""Export configuration types and limits from the server's authoritative schema."""
import argparse
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from webapp.config.schema import SETTINGS


def render():
    custom = {'download_methods': 'Provider[] | null',
              'download_channels': 'DownloadChannel[]', 'js_runtimes': 'unknown'}
    lines = [
        '// Generated by scripts/generate_frontend_contract.py. Edit the Python schema.',
        "export type Provider = 'yt_dlp' | 'yt5s' | 'downmp3' | 'yt1d' | 'bergung';",
        'export interface DownloadChannel {',
        '  id: string; label: string; adapter: string; site_url: string; api_url: string;',
        '  upstream_group: string; resolver_group: string; quota_group: string;',
        '  transfer_limit: number; resolver_limit: number; connection_limit: number;',
        '  task_limit: number; weight: number; verification: string;',
        '}',
        'export interface ConsoleConfig {',
    ]
    for key, spec in SETTINGS.items():
        value_type = custom.get(key) or {str: 'string', int: 'number', bool: 'boolean',
                                       list: 'string[]', type(None): 'null'}[spec.value_type]
        lines.append(f'  {key}: {value_type};')
    lines += ['  oss_access_key_secret_configured?: boolean;',
              '  oss_security_token_configured?: boolean;', '}',
              'export type ConfigKey = keyof ConsoleConfig;',
              'export const constraints: Partial<Record<ConfigKey, readonly [number, number]>> = ' +
              json.dumps({key: spec.limits for key, spec in SETTINGS.items() if spec.limits},
                         indent=2) + ';',
              'export const secretKeys = ["oss_access_key_secret", "oss_security_token"] as const;',
              'export const defaultConfig: ConsoleConfig = ' +
              json.dumps({key: spec.default_value() for key, spec in SETTINGS.items()},
                         ensure_ascii=False, indent=2) + ';', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    target = ROOT / 'frontend/src/generated/config.ts'
    content = render()
    if args.check:
        if not target.is_file() or target.read_text(encoding='utf-8') != content:
            raise SystemExit('Frontend configuration contract is stale. Run this script without --check.')
    else:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding='utf-8')


if __name__ == '__main__':
    main()
